<template>
  <view class="family-page laboratory">
    <view v-if="!selected">
      <view class="lab-hero"><view><text class="eyebrow">MIAO · DISCOVERY CLUB</text><text class="title">好奇心，开机！</text><text class="intro">自己设计实验，用证据找规律，再用没测过的条件检验。和家长一起完成 4 项探究，也能自由探索 13 个模型。</text><text class="hero-badge">离线可玩 · 和家长一起发现</text></view><image class="hero-symbol" src="/static/ui/activities/lab.png" mode="aspectFit" /></view>
      <view class="inquiry-heading"><view><text class="heading">研究工作台</text><text class="muted">已完成 {{ Object.keys(inquiryProgress.completed).length }} / 4 份研究 · 每份留下 3 组以上观察和 1 次新条件检验</text></view><text class="inquiry-label">先预测 · 选证据 · 再验证</text></view>
      <view class="inquiry-grid"><button v-for="item in inquiries" :key="item.id" class="inquiry-card" @click="openInquiry(item.id)"><text class="experiment-area">{{ inquiryProgress.completed[item.id] ? '✓ 已有研究报告，可重做' : '由你决定实验条件' }}</text><text class="experiment-title">{{ item.title }}</text><text class="experiment-question">{{ item.question }}</text><text class="experiment-link">开始探究 →</text></button></view>
      <view class="card research-progress"><text class="heading">热身任务 {{ challengeSummary.completed }} / {{ challengeSummary.total }} 星</text><text class="muted">保留原来的 9 颗任务星。想直接试旋钮，可从下面进入自由探索。</text></view><view class="row section-heading"><text>今天想研究什么？</text><text class="muted">{{ Object.keys(notes).length }} / 13 篇发现</text></view>
      <view class="lab-grid"><button v-for="(e,i) in experiments" :key="e.id" class="experiment-card" @click="open(e)"><view class="row"><image class="experiment-icon" :src="'/static/ui/activities/'+e.icon+'.png'" mode="aspectFit" /><text class="experiment-number">{{ String(i+1).padStart(2,'0') }}</text></view><text class="experiment-area">{{ e.area }}</text><text class="experiment-title">{{ e.title }}</text><text class="experiment-question">{{ e.question }}</text><text v-if="challengeSummary.byExperiment[e.id] !== undefined" class="task-badge">研究任务 {{ challengeSummary.byExperiment[e.id] }} / 3 ★</text><text class="experiment-link">{{ notes[e.id] ? '已有我的发现' : '去试一试' }} →</text></button></view>
    </view>
    <view v-else-if="activeInquiry" class="inquiry-workbench">
      <button class="back link" @click="close">← 研究工作台</button>
      <text class="eyebrow">MIAO · RESEARCH NOTEBOOK</text><text class="title">{{ activeInquiry.title }}</text><text class="intro">{{ activeInquiry.question }}</text>
      <view class="inquiry-steps"><text :class="{current:inquiryPhase==='predict'}">1 预测</text><text :class="{current:inquiryPhase==='collect'}">2 对照</text><text :class="{current:inquiryPhase==='evidence'}">3 解释</text><text :class="{current:['transfer','locked','verified','complete'].includes(inquiryPhase)}">4 检验</text></view>
      <view v-if="inquiryPhase==='predict'" class="card prediction"><text class="heading">先提出一个可检验的想法</text><text class="muted">{{ activeInquiry.fixed }}</text><text class="mission-instruction">{{ activeInquiry.design }}</text><view class="guess-options inquiry-choices"><button v-for="(choice,i) in activeInquiry.choices" :key="choice" :class="['guess',{chosen:inquiryForecast===i}]" @click="inquiryForecast=i">{{ choice }}</button></view><text class="muted">预测可以猜错。完成研究，看的是证据和修正，不是第一次就答对。</text><button class="primary" :disabled="inquiryForecast===null" @click="beginInquiry">留下预测，自己设计对照 →</button><button v-if="inquiryProgress.completed[inquiryId]" class="link" @click="viewInquiryReport">查看上次完成的研究报告</button></view>
      <view v-else :class="['inquiry-layout',{'without-scene':!inquiryCanObserve}]">
        <view v-if="inquiryCanObserve" class="scene-panel"><view class="scene-caption"><text>{{ inquiryPhase==='verified'||inquiryPhase==='complete' ? '新条件的验证结果' : '控制条件，收集证据' }}</text><text>SIMULATION</text></view><canvas canvas-id="lab-stage" id="lab-stage" :width="canvasWidth" :height="canvasHeight" :style="{width:canvasWidth+'px',height:canvasHeight+'px'}" class="lab-canvas"/><view class="result-strip"><text class="result-dot">●</text><text>{{ result.text }}</text></view><text class="model-caption">{{ activeInquiry.fixed }}<text>屏幕简化模型；结果适用于当前固定条件。</text></text></view>
        <view class="experiment-tools inquiry-tools">
          <view v-if="inquiryPhase==='collect'" class="card controls"><text class="heading">自己选条件，至少测 3 组</text><text class="control-lock">先布置条件，按“记录并观察”后才揭晓结果。再调旋钮时，新结果会重新隐藏。</text><text class="muted">{{ activeInquiry.design }}</text><text v-if="inquirySession.records.length" class="control-lock">其他条件已按第一条记录锁定。需要改研究设计，可从头开始。</text><view v-for="k in inquiryKnobs" :key="k.key" class="knob"><view class="row"><text>{{ k.label }}{{ k.key!==activeInquiry.variable ? '（固定条件）' : '（只改变这一项）' }}</text><text class="knob-value">{{ knobText(k) }}</text></view><slider :min="k.min" :max="k.max" :step="k.step" :value="params[k.key]" :disabled="!!inquirySession.records.length && k.key!==activeInquiry.variable" activeColor="#278b7a" backgroundColor="#dfede9" :block-size="24" @changing="changeInquiry(k,$event)" @change="changeInquiry(k,$event)" :aria-label="k.label"/></view><button class="secondary" @click="recordInquiry">记录并观察这组条件（{{ inquirySession.records.length }} / 至少 3）</button><button class="primary" :disabled="inquirySession.records.length<3" @click="inquiryPhase='evidence'">用这些记录解释规律 →</button></view>
          <view v-if="inquirySession.records.length" class="card inquiry-records"><text class="heading">我的证据表</text><text v-if="inquiryPhase==='evidence'" class="muted">选两条关键记录，再选择能解释全部记录的结论。</text><view v-for="(record,i) in inquirySession.records" :key="i" :class="['observation',{evidence:selectedEvidence.includes(i)}]"><view class="row"><text class="record-title">记录 {{ i+1 }} · {{ parameterText(record.params) }}</text><button v-if="inquiryPhase==='evidence'" class="evidence-button" @click="toggleEvidence(i)">{{ selectedEvidence.includes(i)?'✓ 关键证据':'选作证据' }}</button></view><text>{{ observationText(record) }}</text></view></view>
          <view v-if="inquiryPhase==='evidence'" class="card"><text class="heading">证据支持哪种解释？</text><text class="muted">最初猜想：{{ activeInquiry.choices[inquirySession.prediction] }}</text><view class="guess-options inquiry-choices"><button v-for="(choice,i) in activeInquiry.choices" :key="choice" :class="['guess',{chosen:inquiryConclusion===i}]" @click="inquiryConclusion=i">{{ choice }}</button></view><button class="primary" @click="acceptInquiryEvidence">检查解释，进入新条件 →</button><button class="link" @click="inquiryPhase='collect'">还缺证据，回去补测</button></view>
          <view v-if="inquiryPhase==='transfer'" class="card transfer-plan"><text class="heading">给规律一次真正的考验</text><text class="muted">选择一组没记录过的条件。结果和画面会在锁定预测后，通过“实际验证”揭晓。</text><text v-if="['shadow','pressure'].includes(selected.id)" class="reference-note">参照：记录 {{ selectedEvidence[0]+1 }} · {{ observationText(inquirySession.records[selectedEvidence[0]]) }}</text><text class="muted">固定条件：{{ fixedInquiryText }}</text><view class="knob"><view class="row"><text>{{ inquiryVariableKnob.label }}</text><text class="knob-value">{{ knobText(inquiryVariableKnob) }}</text></view><slider :min="inquiryVariableKnob.min" :max="inquiryVariableKnob.max" :step="inquiryVariableKnob.step" :value="params[activeInquiry.variable]" activeColor="#278b7a" :block-size="24" @change="changeInquiry(inquiryVariableKnob,$event)" :aria-label="inquiryVariableKnob.label"/></view><text class="heading">还没看到结果时，我预测</text><view class="guess-options inquiry-choices"><button v-for="(choice,i) in activeInquiry.transferChoices" :key="choice" :class="['guess',{chosen:transferForecast===i}]" @click="transferForecast=i">{{ choice }}</button></view><button class="primary" :disabled="transferForecast===null" @click="lockTransfer">锁定条件和预测</button></view>
          <view v-if="inquiryPhase==='locked'" class="card"><text class="heading">预测已锁定，现在实际检验</text><text class="mission-instruction">{{ parameterText(inquirySession.transfer.params) }}</text><text class="muted">我的预测：{{ activeInquiry.transferChoices[inquirySession.transfer.prediction] }}</text><button class="primary" @click="verifyTransfer">实际验证，揭晓结果 →</button></view>
          <view v-if="inquiryPhase==='verified'" class="card"><text class="heading">用结果修正判断</text><text class="muted">先前预测：{{ activeInquiry.transferChoices[inquirySession.transfer.prediction] }}</text><text class="mission-instruction">实际观察：{{ observationText(inquirySession.transfer.record) }}</text><text v-if="['shadow','pressure'].includes(selected.id)" class="reference-note">参照记录 {{ selectedEvidence[0]+1 }}：{{ observationText(inquirySession.records[selectedEvidence[0]]) }}</text><text class="muted">猜错不是失败。根据这次结果，我现在判断：</text><view class="guess-options inquiry-choices"><button v-for="(choice,i) in activeInquiry.transferChoices" :key="choice" :class="['guess',{chosen:inquiryRevision===i}]" @click="inquiryRevision=i">{{ choice }}</button></view><button class="primary" :disabled="inquiryRevision===null" @click="finishInquiry">完成并保存研究报告</button></view>
          <view v-if="inquiryPhase==='complete'" class="card inquiry-complete"><text class="heading">✓ 研究报告已保存在本机</text><text class="mission-instruction">{{ activeInquiry.conclusion }}</text><view class="observation"><text class="record-title">新条件检验 · {{ parameterText(inquirySession.transfer.params) }}</text><text>事先预测：{{ activeInquiry.transferChoices[inquirySession.transfer.prediction] }}</text><text>实际观察：{{ observationText(inquirySession.transfer.record) }}</text><text>验证后判断：{{ activeInquiry.transferChoices[inquirySession.revision] }}</text></view><text class="muted">用了 {{ inquirySession.records.length }} 组对照记录，并验证了一个未测条件。每项研究记一份完成，重复探索不会叠加数量。</text><view class="challenge"><text>和家长继续追问</text><text>{{ activeInquiry.extension }}</text></view><text class="source">知识依据：OpenStax · College Physics 2e · 当前为简化模型</text><button class="secondary" @click="restartInquiry">换一套条件，再研究一次</button><button class="link" @click="close">返回研究工作台</button></view>
          <text v-if="inquiryFeedback" class="task-feedback" role="status">{{ inquiryFeedback }}</text><button v-if="inquiryPhase!=='complete'" class="link" @click="restartInquiry">清空本次条件，重新设计</button>
        </view>
      </view>
    </view>
    <view v-else>
      <button class="back link" @click="close">← 全部实验</button>
      <text class="eyebrow">{{ selected.area }} · 小小研究员</text><text class="title">{{ selected.title }}</text><text class="intro">{{ selected.question }}</text>
      <view v-if="tasksForSelected.length" class="mode-switch"><button :class="{chosen:experimentMode==='challenge'}" @click="setMode('challenge')">研究任务 · 3 级</button><button :class="{chosen:experimentMode==='free'}" @click="setMode('free')">自由探索</button></view>
      <view v-if="task" class="card mission"><text class="eyebrow">第 {{ task.level }} 级 · {{ task.type==='compare'?'对照实验':task.type==='transfer'?'迁移挑战':'达成目标' }}</text><text class="heading">{{ task.title }}</text><text class="mission-instruction">{{ task.instruction }}</text><view class="task-tabs"><button v-for="item in tasksForSelected" :key="item.id" :class="{chosen:taskId===item.id}" @click="selectTask(item.id)">{{ item.level }} {{ labProgress.completed[item.id] ? '★' : '☆' }}</button></view><text class="muted">目标：{{ task.target }}</text><text v-if="labProgress.completed[task.id]" class="saved">这颗星已收藏，重玩不会重复增加。</text></view>
      <view v-if="!revealed" class="card prediction"><text class="heading">① {{ task && task.type==='transfer' ? '先预测，再动手检验' : '先留下你的猜想' }}</text><text class="muted">猜错也没关系，发现的乐趣就在这里。</text><view class="guess-options"><button v-for="(g,i) in predictionChoices" :key="g" :class="['guess',{chosen:guess===i}]" @click="guess=i">{{ g }}</button></view><button class="primary" :disabled="guess===null" @click="begin">带着猜想去试试 →</button></view>
      <view v-else class="experiment-layout">
        <view class="scene-panel"><view class="scene-caption"><text>② 动手改变，仔细观察</text><text>SIMULATION</text></view><canvas canvas-id="lab-stage" id="lab-stage" :width="canvasWidth" :height="canvasHeight" :style="{width:canvasWidth+'px',height:canvasHeight+'px'}" class="lab-canvas"/><view class="result-strip"><text class="result-dot">●</text><text>{{ result.text }}</text></view><button v-if="animated" class="secondary run" @click="run">{{ timer ? '正在观察…' : '试验一次 ▶' }}</button><button v-if="selected.id==='sound'" class="secondary run" @click="listen">听一秒 ♪</button><text class="model-caption">屏幕上的简化模型 · 一次只改变一个条件更容易看清</text></view>
        <view class="experiment-tools"><view class="card controls"><text class="heading">实验旋钮</text><view v-for="k in selected.knobs" :key="k.key" class="knob"><view class="row"><text>{{ k.label }}</text><text class="knob-value">{{ knobText(k) }}</text></view><slider :min="k.min" :max="k.max" :step="k.step" :value="params[k.key]" activeColor="#278b7a" backgroundColor="#dfede9" :block-size="24" @changing="change(k,$event)" @change="change(k,$event)" :aria-label="k.label"/></view><button class="link" @click="reset">恢复初始条件</button></view>
        <view v-if="task" class="card task-records"><text class="heading">③ 留下实验记录</text><text class="muted">{{ task.type==='compare' ? '对照任务需要两次实际记录，并且只改变一个条件。' : '调整后按下面的按钮，保存这一次的条件和观察结果。' }}</text><view v-for="(record,i) in observations" :key="i" class="observation"><text class="record-title">记录 {{ i+1 }} · {{ parameterText(record.params) }}</text><text>{{ observationText(record) }}</text></view><view v-if="task.type==='transfer' && observations.length" class="conclusion"><text class="heading">我的结论</text><text class="muted">{{ task.conclusionPrompt }}</text><text class="muted">先前猜错也没关系，可以根据证据修正想法。</text><view class="guess-options"><button v-for="(item,i) in task.conclusions" :key="item" :class="['guess',{chosen:conclusion===i}]" :disabled="taskPassed" @click="conclusion=i">{{ item }}</button></view></view><view v-if="!taskPassed" class="record-actions"><button class="secondary" @click="captureCurrent">记录当前条件（{{ observations.length }} / {{ task.type==='compare'?2:1 }}）</button><button v-if="observations.length" class="link" @click="clearObservations">清空记录，重新比较</button><button class="primary" :disabled="observations.length < (task.type==='compare'?2:1)" @click="checkTask">检查任务</button></view><text v-if="taskFeedback" class="task-feedback">{{ taskFeedback }}</text><text v-if="taskPassed" class="saved">{{ earnedStar ? '★ 首次独立完成，星星已保存在本机' : usedHelp ? '已借助说明完成，本次不增加独立星星' : '本次任务练习已完成' }}</text><button v-if="taskPassed" class="secondary" @click="nextTask">{{ task.level < 3 ? '下一项研究 →' : '继续自由探索 →' }}</button><button v-if="taskPassed && !earnedStar && !labProgress.completed[task.id]" class="link" @click="selectTask(task.id)">重新独立挑战</button></view>
        <view class="card discovery"><text class="heading">{{ task ? '④' : '③' }} 和家长说说你的发现</text><text class="guess-review">我的猜想：{{ predictionChoices[guess] }}</text><button v-if="task && !taskPassed && !showExplanation" class="link" @click="learnExplanation">先看学习说明（本次不计独立星）</button><text v-if="!task || taskPassed || showExplanation" class="muted">{{ selected.explain }}</text><text v-else class="muted">先用记录检验猜想，完成本任务后再一起读规律。也可以主动打开学习说明。</text><view v-if="!task || taskPassed || showExplanation" class="challenge"><text>再试一步</text><text>{{ selected.challenge }}</text></view><textarea v-model="note" @input="saved=false" maxlength="280" class="note" placeholder="我发现……（可以请家长帮忙记）" :auto-height="true"/><button class="primary" @click="save">保存我的发现</button><text v-if="saved" class="saved">已保存在这台设备</text><text class="source">知识依据：{{ selected.id==='moon'?'NASA · 月相':'OpenStax · College Physics 2e' }}</text></view></view>
      </view>
    </view>
    <text v-if="error" class="error">{{ error }}</text>
  </view>
</template>
<script>
import { EXPERIMENTS, defaults, observe, readNotebook, saveNote, LAB_KEY } from '@/lab/experiments.mjs'
import { LAB_TASKS, readLabChallenges, summarizeLabChallenges, captureLabObservation, evaluateLabTask, createLabChallengeStore } from '@/lab/challenges.mjs'
import { LAB_INQUIRIES, createInquirySession, startInquiry, addInquiryObservation, evaluateInquiryEvidence, lockInquiryTransfer, verifyInquiryTransfer, createLabInquiryStore, emptyLabInquiries, inquiryDefaults } from '@/lab/inquiries.mjs'
import { drawExperiment } from '@/lab/draw.mjs'
export default {
  data(){return {experiments:EXPERIMENTS,selected:null,params:{},guess:null,revealed:false,note:'',notes:{},saved:false,error:'',canvasWidth:300,canvasHeight:180,progress:0,timer:null,resizeTimer:null,audio:null,experimentMode:'free',taskId:'',labProgress:{version:1,completed:{}},observations:[],taskPassed:false,taskFeedback:'',usedHelp:false,showExplanation:false,earnedStar:false,conclusion:null,inquiries:LAB_INQUIRIES,inquiryId:'',inquirySession:null,inquiryProgress:emptyLabInquiries(),inquiryPhase:'predict',inquiryForecast:null,inquiryConclusion:null,selectedEvidence:[],transferForecast:null,inquiryRevision:null,inquiryFeedback:''}},
  computed:{activeInquiry(){return this.inquiries.find(item=>item.id===this.inquiryId)||null},inquiryCanObserve(){if(['collect','evidence'].includes(this.inquiryPhase))return !!this.inquirySession?.records.some(record=>this.selected.knobs.every(k=>record.params[k.key]===this.params[k.key]));return ['verified','complete'].includes(this.inquiryPhase)},inquiryKnobs(){return this.selected.knobs.map(k=>this.selected.id==='lever'&&k.key==='left'?{...k,max:2}:this.selected.id==='float'&&k.key==='mass'?{...k,min:41}:k)},inquiryVariableKnob(){return this.inquiryKnobs.find(k=>k.key===this.activeInquiry.variable)},fixedInquiryText(){return this.selected.knobs.filter(k=>k.key!==this.activeInquiry.variable).map(k=>k.label+' '+this.params[k.key]+k.unit).join(' / ')||this.activeInquiry.fixed},challengeSummary(){return summarizeLabChallenges(this.labProgress)},tasksForSelected(){return LAB_TASKS.filter(task=>task.experiment===this.selected?.id)},task(){return this.experimentMode==='challenge'?LAB_TASKS.find(task=>task.id===this.taskId):null},predictionChoices(){return this.task?.predictions||this.selected.guesses},result(){if(this.activeInquiry&&!this.inquiryCanObserve)return {text:'结果待实际验证后揭晓'};return this.selected?observe(this.selected.id,this.params):{text:''}},animated(){return this.selected&&['ramp','friction','parachute'].includes(this.selected.id)}},
  onLoad(){const errors=[];try{this.notes=readNotebook(uni.getStorageSync(LAB_KEY)).notes}catch(e){errors.push(e.message)}try{this.labProgress=this.challengeStore().read()}catch(e){errors.push(e.message)}try{this.inquiryProgress=this.inquiryStore().read()}catch(e){errors.push(e.message)}this.error=errors.join(' ')} ,
  onShow(){if(this.revealed)this.$nextTick(this.measure)},
  onResize(){if(this.revealed)this.$nextTick(this.measure)},
  onHide(){this.stop();clearTimeout(this.resizeTimer);this.stopAudio()},onUnload(){this.stop();clearTimeout(this.resizeTimer);if(this.audio)this.audio.destroy()},
  methods:{
    inquiryStore(){return createLabInquiryStore({get:key=>uni.getStorageSync(key),set:(key,value)=>uni.setStorageSync(key,value)})},
    openInquiry(id){
      const task=this.inquiries.find(item=>item.id===id);if(!task)return
      this.stop();this.stopAudio();this.inquiryId=id;this.selected=this.experiments.find(e=>e.id===task.experiment);this.params=inquiryDefaults(id);this.inquirySession=createInquirySession(id);this.inquiryPhase='predict';this.inquiryForecast=null;this.inquiryConclusion=null;this.selectedEvidence=[];this.transferForecast=null;this.inquiryRevision=null;this.inquiryFeedback='';this.revealed=false;this.experimentMode='inquiry';uni.pageScrollTo({scrollTop:0,duration:0})
    },
    restartInquiry(){this.openInquiry(this.inquiryId)},
    beginInquiry(){try{this.inquirySession=startInquiry(this.inquirySession,this.inquiryForecast);this.inquiryPhase='collect';this.revealed=true;this.$nextTick(this.measure)}catch(error){this.inquiryFeedback=error.message}},
    changeInquiry(k,event){if(this.inquiryPhase==='collect'&&this.inquirySession.records.length&&k.key!==this.activeInquiry.variable)return;if(!['collect','transfer'].includes(this.inquiryPhase))return;this.params[k.key]=Number(event.detail.value);if(this.inquiryCanObserve)this.$nextTick(this.measure)},
    recordInquiry(){try{this.inquirySession=addInquiryObservation(this.inquirySession,this.params);this.selectedEvidence=[];this.inquiryConclusion=null;this.inquiryFeedback='观察已记录。请换一个条件，其他条件保持不变。';this.$nextTick(this.measure)}catch(error){this.inquiryFeedback=error.message}},
    toggleEvidence(index){this.selectedEvidence=this.selectedEvidence.includes(index)?this.selectedEvidence.filter(i=>i!==index):[...this.selectedEvidence,index].slice(-2)},
    acceptInquiryEvidence(){
      this.inquirySession={...this.inquirySession,conclusion:this.inquiryConclusion,evidence:[...this.selectedEvidence]}
      const result=evaluateInquiryEvidence(this.inquirySession);this.inquiryFeedback=result.feedback
      if(result.passed){this.inquiryPhase='transfer';this.transferForecast=null;this.params={...this.inquirySession.records[0].params}}
    },
    lockTransfer(){try{this.inquirySession=lockInquiryTransfer(this.inquirySession,this.params,this.transferForecast);this.inquiryPhase='locked';this.inquiryFeedback='条件和预测已锁定，验证前不会显示新结果。'}catch(error){this.inquiryFeedback=error.message}},
    verifyTransfer(){try{this.inquirySession=verifyInquiryTransfer(this.inquirySession);this.params={...this.inquirySession.transfer.params};this.inquiryPhase='verified';this.inquiryRevision=null;this.inquiryFeedback='请比较预测与实际结果，再留下现在的判断。';this.$nextTick(this.measure)}catch(error){this.inquiryFeedback=error.message}},
    finishInquiry(){
      try{this.inquirySession={...this.inquirySession,revision:this.inquiryRevision};this.inquiryProgress=this.inquiryStore().complete(this.inquirySession);this.inquiryPhase='complete';this.inquiryFeedback='';this.error=''}catch(error){this.inquiryFeedback=error.message+' 本次证据仍在，可以修正判断或再次保存。'}
    },
    viewInquiryReport(){const report=this.inquiryProgress.completed[this.inquiryId]?.report;if(!report)return;this.inquirySession=JSON.parse(JSON.stringify(report));this.selectedEvidence=[...report.evidence];this.inquiryPhase='complete';this.params={...report.transfer.params};this.revealed=true;this.$nextTick(this.measure)},
    challengeStore(){return createLabChallengeStore({get:key=>uni.getStorageSync(key),set:(key,value)=>uni.setStorageSync(key,value)})},
    setMode(mode){
      this.stop();clearTimeout(this.resizeTimer);this.stopAudio();this.experimentMode=mode;this.guess=null;this.revealed=false;this.progress=0
      this.observations=[];this.taskPassed=false;this.taskFeedback='';this.usedHelp=false;this.showExplanation=false;this.earnedStar=false;this.conclusion=null
      if(mode==='challenge'){
        const available=LAB_TASKS.filter(task=>task.experiment===this.selected.id)
        const next=available.find(task=>!this.labProgress.completed[task.id])||available[0]
        if(next)this.selectTask(next.id)
      }else{this.taskId='';this.params=defaults(this.selected)}
    },
    selectTask(id){
      const task=LAB_TASKS.find(item=>item.id===id&&item.experiment===this.selected.id)
      if(!task)return
      this.stop();clearTimeout(this.resizeTimer);this.stopAudio();this.experimentMode='challenge';this.taskId=id;this.params={...task.initial};this.progress=0;this.guess=null;this.revealed=false;this.observations=[];this.taskPassed=false;this.taskFeedback='';this.usedHelp=false;this.showExplanation=false;this.earnedStar=false;this.conclusion=null
    },
    captureCurrent(){
      if(!this.task||!this.revealed||this.taskPassed)return
      try{const record=captureLabObservation(this.task.id,this.params);const needed=this.task.type==='compare'?2:1;this.observations=[...this.observations,record].slice(-needed);this.taskFeedback=needed===2&&this.observations.length===1?'第一条记录已留下，只改变任务指定的一个条件，再按一次记录。':'观察已记录，可以检查任务。'}catch(error){this.error=error.message}
    },
    clearObservations(){this.observations=[];this.taskFeedback='记录已清空，可以重新做一次对照。'},
    parameterText(params){return this.selected.knobs.map(knob=>knob.label+' '+params[knob.key]+knob.unit).join(' / ')},
    observationText(record){return observe(this.selected.id,record.params).text},
    checkTask(){
      if(!this.task||!this.revealed)return
      try{
        const options={prediction:this.guess,conclusion:this.conclusion,assisted:this.usedHelp}
        const result=evaluateLabTask(this.task.id,this.observations,options)
        this.taskFeedback=result.feedback
        if(!result.passed)return
        if(!result.independent){this.taskPassed=true;return}
        const already=!!this.challengeStore().read().completed[this.task.id]
        this.labProgress=this.challengeStore().complete(this.task.id,this.observations,options)
        this.earnedStar=!already;this.taskPassed=true;this.error=''
        if(already)this.taskFeedback='再次独立完成了！这颗星已经收藏，重玩不重复增加。'
      }catch(error){this.taskPassed=false;this.earnedStar=false;this.error=error.message+' 条件和观察仍留在这里，可以再次点“检查任务”重试保存。'}
    },
    learnExplanation(){this.usedHelp=true;this.showExplanation=true;this.taskFeedback='这次借助说明学习，完成后不增加独立星。理解后可重新发起独立挑战。'},
    nextTask(){const next=this.tasksForSelected.find(item=>item.level>this.task.level);if(next)this.selectTask(next.id);else this.setMode('free')},
    open(e){this.inquiryId='';this.stop();this.stopAudio();this.selected=e;this.params=defaults(e);this.guess=null;this.revealed=false;this.note=this.notes[e.id]?this.notes[e.id].text:'';this.saved=false;this.progress=0;this.setMode(LAB_TASKS.some(task=>task.experiment===e.id)?'challenge':'free');uni.pageScrollTo({scrollTop:0,duration:0})},
    close(){this.inquiryId='';this.stop();clearTimeout(this.resizeTimer);this.stopAudio();this.selected=null;this.revealed=false},
    begin(){if(this.guess===null)return;this.revealed=true;this.$nextTick(this.measure)},
    measure(){uni.createSelectorQuery().in(this).select('.scene-panel').boundingClientRect(r=>{if(!r||!this.revealed)return;this.canvasWidth=Math.max(180,Math.floor(r.width));this.canvasHeight=Math.round(this.canvasWidth*.6);this.$nextTick(()=>{clearTimeout(this.resizeTimer);this.resizeTimer=setTimeout(this.draw,100)})}).exec()},
    draw(){if(!this.selected||!this.revealed||(this.activeInquiry&&!this.inquiryCanObserve))return;const c=uni.createCanvasContext('lab-stage',this);c.scale(this.canvasWidth/600,this.canvasHeight/360);drawExperiment(c,this.selected,this.params,this.result,this.progress);c.draw()},
    change(k,event){this.stop();this.progress=0;this.params[k.key]=Number(event.detail.value);this.draw()},
    knobText(k){if(this.selected.id==='materials')return this.selected.labels[this.params[k.key]];if(this.selected.id==='sound'&&k.key==='tone')return ['低','中','高'][this.params[k.key]];if(k.max===1)return this.selected.id==='poles'?(this.params[k.key]?'已翻转':'未翻转'):(this.params[k.key]?'已接通':'未接通');return this.params[k.key]+k.unit},
    reset(){this.stop();this.params=this.task?{...this.task.initial}:defaults(this.selected);this.progress=0;this.draw()},
    run(){this.stop();this.progress=0;const speed=this.result.value;const duration=this.selected.id==='ramp'?2.8/speed:this.selected.id==='friction'?speed:14/speed;const start=Date.now();this.timer=setInterval(()=>{this.progress=Math.min(1,(Date.now()-start)/(Math.max(.6,duration)*1000));this.draw();if(this.progress===1)this.stop()},40)},
    stop(){clearInterval(this.timer);this.timer=null},
    stopAudio(){if(this.audio)this.audio.stop()},
    listen(){this.stopAudio();if(!this.audio){this.audio=uni.createInnerAudioContext();this.audio.onError(()=>{this.error='声音暂时没有播放出来，可以先观察波浪。'})}this.audio.src='/static/lab/tone-'+this.result.value+'.m4a';this.audio.volume=this.params.volume/3;this.audio.play()},
    save(){try{const next=saveNote({get:k=>uni.getStorageSync(k),set:(k,v)=>uni.setStorageSync(k,v)},this.selected.id,this.note,Date.now());this.notes=next.notes;this.saved=true;this.error=''}catch(e){this.error=e.message;this.saved=false}}
  }
}
</script>
